SELECT w.w_warehouse_id, w.w_warehouse_name, COUNT(cr.cr_order_number) AS total_returns, SUM(cr.cr_net_loss) AS total_net_loss, SUM(cr.cr_return_amt_inc_tax) AS total_return_amount_inc_tax, AVG(cr.cr_return_quantity) AS avg_return_quantity, CASE WHEN SUM(cr.cr_net_loss) > 10000 THEN 'High Loss' WHEN SUM(cr.cr_net_loss) BETWEEN 5000 AND 10000 THEN 'Medium Loss' ELSE 'Low Loss' END AS loss_category, RANK() OVER (ORDER BY SUM(cr.cr_net_loss) DESC) AS net_loss_rank, DENSE_RANK() OVER (ORDER BY SUM(cr.cr_return_quantity) DESC) AS return_qty_dense_rank FROM catalog_returns cr JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk GROUP BY w.w_warehouse_id, w.w_warehouse_name ORDER BY total_net_loss DESC LIMIT 10
